function icon(name, cls=''){return `<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name] || icons.box}"/></svg>`;}
function buddy(white=false){return `<img class="buddy-logo universe-symbol ${white?'on-dark':''}" src="assets/universe-symbol.png" alt="" aria-hidden="true">`;}
function brandLogo(){return '<span class="brand-lockup"><img class="universe-wordmark" src="assets/universe-logo.png" alt="Universe Solusi Digital"><span class="app-brand-name">USDpedia</span></span>';}
const DEMO_IDR_MULTIPLIER=190;
const demoToIdr=n=>Math.round(n*DEMO_IDR_MULTIPLIER);
const platforms={amazon:{name:'Amazon',mark:'a',color:'amazon'},flipkart:{name:'Flipkart',mark:'f',color:'flipkart'},blinkit:{name:'Blinkit',mark:'b',color:'blinkit'},zepto:{name:'Zepto',mark:'z',color:'zepto'},instamart:{name:'Instamart',mark:'s',color:'instamart'}};
function platformLogo(id,mini=false){const p=platforms[id];return `<span class="${mini?'platform-mini':'platform-logo'} ${p.color}" aria-label="${p.name}">${p.mark}</span>`;}
