const defaultStore={currency:'IDR',name:'Edvan',postal:'560001',saved:[1,4],thresholds:{},alerts:[],payment:{issuer:'HDFC',type:'Kredit',last4:'4242'},settings:{priceAlerts:true,stockAlerts:true,personalDeals:true,analytics:false},onboarded:false,reports:[]};
let store;
try{const saved=JSON.parse(localStorage.getItem('buybuddy-v1')||'null');store=saved?{...defaultStore,...saved,currency:saved.currency||'INR',settings:{...defaultStore.settings,...saved.settings}}:structuredClone(defaultStore);if(!Array.isArray(store.saved))store.saved=[];if(!Array.isArray(store.alerts))store.alerts=[];}catch{store=structuredClone(defaultStore);}
let page='home',category='Semua',query='',catalogSort='popular',fabOpen=false,currentProduct=1,compareMode='standard',compareSort='price',selectedPlatforms=[],lastUpdated=new Date(),onboardStep=0,formPaymentType='Kredit',lastFocused=null,toastTimer;
const $=sel=>document.querySelector(sel);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'Rp'+Math.round(n).toLocaleString('id-ID');
if(store.currency!=='IDR'){
  for(const id of Object.keys(store.thresholds))store.thresholds[id]=demoToIdr(store.thresholds[id]);
  store.currency='IDR';
  persist();
}
products.find(p=>p.id===4).badge='Hemat '+money(demoToIdr(4000));
function persist(){try{localStorage.setItem('buybuddy-v1',JSON.stringify(store));}catch{toast('Penyimpanan browser penuh. Perubahan hanya tersimpan selama sesi ini.');}}
function product(id){return products.find(p=>p.id===Number(id))||products[0];}
function lowest(p){return Math.min(...p.offers.filter(o=>o.stock).map(o=>o.price));}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3600);}
const navigation=[['home','home','Ringkasan'],['explore','grid','Jelajahi produk'],['watchlist','heart','Daftar pantauan'],['payments','wallet','Pembayaran']];
function navButtons(mobile=false){return navigation.map(([id,i,label])=>`<button class="${mobile?'':'nav-btn '}${page===id?'active':''}" data-action="nav" data-page="${id}" ${page===id?'aria-current="page"':''}>${icon(i)}<span>${mobile?({home:'Beranda',explore:'Jelajahi',watchlist:'Pantauan',payments:'Kartu'}[id]):label}</span>${!mobile&&id==='watchlist'?`<span class="count-badge">${store.saved.length}</span>`:''}</button>`).join('');}
function render(){
  $('#app').innerHTML=`<div class="menu-backdrop" data-action="close-menu"></div><aside class="sidebar"><button class="brand" data-action="nav" data-page="home" aria-label="Universe Solusi Digital — USDpedia Beranda">${brandLogo()}</button><p class="nav-label">RUANG BELANJAMU</p><nav class="nav-list" aria-label="Navigasi utama">${navButtons()}</nav><div style="height:28px"></div><p class="nav-label">LAINNYA</p><nav class="nav-list" aria-label="Bantuan dan pengaturan"><button class="nav-btn ${page==='settings'?'active':''}" data-action="nav" data-page="settings">${icon('settings')}Pengaturan</button><button class="nav-btn ${page==='help'?'active':''}" data-action="nav" data-page="help">${icon('help')}Bantuan & FAQ</button></nav><div class="sidebar-bottom"><div class="buddy-status"><div class="row"><span class="dot"></span><strong>Buddy siap membantu</strong></div><p>Bandingkan produk kapan saja lewat tombol Buddy.</p><button class="btn btn-secondary" data-action="onboard">${icon('spark','small-icon')}Kenalan dengan Buddy</button></div><div class="row" style="padding:0 12px;color:#95a49a;font-size:9px">${icon('shield','small-icon')}Privasimu tetap milikmu</div><p class="sidebar-foot">USDpedia · Universe Solusi Digital<br>Dibuat untuk keputusan yang lebih baik.</p></div></aside><div class="layout"><header class="topbar"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Buka menu">${icon('menu')}</button><button class="brand mobile-logo" data-action="nav" data-page="home">${brandLogo()}</button><label class="searchbox">${icon('search','small-icon')}<input id="global-search" type="search" placeholder="Cari produk, merek, atau kategori…" aria-label="Cari produk" value="${esc(query)}"><kbd>⌘ K</kbd></label><div class="topbar-right"><button class="row location" data-action="location">${icon('location','small-icon')}Kirim ke <strong>${esc(store.postal)}</strong>${icon('down','small-icon')}</button><span class="demo-tag">DATA DEMO</span><button class="icon-btn notification-btn" data-action="notifications" aria-label="Notifikasi">${icon('bell')}</button><button class="avatar" data-action="profile" aria-label="Profil ${esc(store.name)}">${esc(store.name.slice(0,2).toUpperCase())}</button></div></header><main class="content" id="main-content"></main></div><nav class="mobile-nav" aria-label="Navigasi seluler">${navButtons(true)}</nav><div class="floating-buddy" id="fab-root"></div>`;
  renderMain();renderFab();
}
function mobileSearch(){return `<label class="searchbox search-mobile" style="display:${window.innerWidth<=560?'flex':'none'}">${icon('search','small-icon')}<input id="mobile-search" type="search" placeholder="Cari produk atau merek…" aria-label="Cari produk" value="${esc(query)}"></label>`;}
function heading(title,sub='',action=''){return `<div class="page-heading"><div><p class="greeting">Halo, ${esc(store.name)} <span class="wave">✦</span></p><h1>${title}</h1>${sub?`<p class="page-subtitle">${sub}</p>`:''}</div>${action}</div>`;}
function categoryButtons(){return `<div class="category-row">${[['Semua','grid'],['Elektronik','phone'],['Fashion','bag'],['Kebutuhan harian','grocery']].map(([c,i])=>`<button class="category ${category===c?'active':''}" data-action="category" data-category="${c}" aria-pressed="${category===c}">${icon(i)}${c==='Kebutuhan harian'?'Harian':c}</button>`).join('')}</div>`;}
function productCard(p,watch=false){const min=lowest(p);return `<article class="product-card"><div class="product-visual ${p.bg}"><span class="product-badge ${p.badgeType==='orange'?'orange-badge':''}">${icon(p.badgeType==='orange'?'tag':'trending','small-icon').replace('small-icon','small-icon" style="width:9px;height:9px')}${p.badge}</span><button class="icon-btn save-btn ${store.saved.includes(p.id)?'saved':''}" data-action="save" data-id="${p.id}" aria-label="${store.saved.includes(p.id)?'Hapus dari':'Tambahkan ke'} pantauan ${p.name}" aria-pressed="${store.saved.includes(p.id)}">${icon('heart')}</button><img src="assets/${p.asset}.svg" alt="${p.name}" loading="lazy"></div><div class="product-info"><p class="product-meta">${p.brand} / ${p.category==='Kebutuhan harian'?'Harian':p.category}</p><h3 class="product-name">${p.name}</h3><p class="product-spec">${p.spec}</p><div class="rating-line"><span class="star">★</span><b>${p.rating}</b><span>(${p.reviews} ulasan)</span></div><div class="price-row"><strong>${money(min)}</strong><del>${money(p.mrp)}</del></div><div class="price-caption"><span class="dot" style="width:4px;height:4px"></span>Harga terendah dari ${p.offers.filter(o=>o.stock).length} toko tersedia</div><div class="platform-stack">${p.offers.map(o=>platformLogo(o.platform,true)).join('')}<span>Hemat ${money(p.mrp-min)}</span></div><button class="btn" data-action="compare" data-id="${p.id}" data-mode="standard">${icon('compare','small-icon')}Bandingkan harga${icon('arrow','small-icon')}</button></div>${watch?`<div class="watch-threshold"><span>${store.thresholds[p.id]?`Target <b>${money(store.thresholds[p.id])}</b>`:'Belum ada target harga'}</span><button class="text-btn" style="font-size:8px" data-action="alert" data-id="${p.id}">${store.thresholds[p.id]?'Ubah':'Atur'}${icon('bell','small-icon')}</button></div>`:''}</article>`;}
function filteredProducts(){let list=products.filter(p=>(category==='Semua'||p.category===category)&&(!query||`${p.name} ${p.brand} ${p.spec} ${p.category}`.toLowerCase().includes(query.toLowerCase())));if(catalogSort==='price')list.sort((a,b)=>lowest(a)-lowest(b));if(catalogSort==='savings')list.sort((a,b)=>(b.mrp-lowest(b))-(a.mrp-lowest(a)));return list;}
function emptyProducts(){return `<div class="empty">${icon('search')}<h3>Produk belum ditemukan</h3><p>Coba nama merek lain atau tampilkan semua kategori.</p><button class="btn btn-soft" data-action="reset-search">Tampilkan semua produk</button></div>`;}
function home(){return `${heading('Belanja cerdas, tanpa ribet.', '',`<span class="date-label">Jumat, 13 November 2026</span>`)}${mobileSearch()}<section class="hero" aria-label="Promo pilihan"><div class="hero-copy"><div class="eyebrow">${icon('spark','small-icon')}TEMAN BELANJA, BUKAN TEBAK-TEBAKAN</div><h2>Barangnya sama.<br><span>Harganya beda.</span></h2><p>Buddy cek harganya. Kamu pilih yang terbaik.<br>Hemat sampai ${money(demoToIdr(10000))} untuk Sony WH-1000XM5.</p><button class="btn btn-primary" data-action="compare" data-id="1" data-mode="standard">Temukan harga terbaik${icon('arrow','small-icon')}</button></div><div class="hero-art" aria-hidden="true"><div class="hero-ring"></div><img class="hero-product" src="assets/headphones.svg" alt=""><div class="hero-float">${platformLogo('flipkart')}<div><small>Flipkart</small><strong>${money(product(1).offers.find(o=>o.platform==='flipkart').price)}</strong></div></div><div class="hero-float second">${platformLogo('amazon')}<div><small>Harga terbaik di Amazon</small><strong>${money(lowest(product(1)))} <span style="font-size:9px;color:#087f69">↘</span></strong></div></div><div class="saving-tag">LEBIH HEMAT<strong>${money(demoToIdr(2000))}</strong><span>antar toko</span></div></div></section><div class="workspace-grid"><section><div class="section-head"><div><h2>Pilihan untuk kamu</h2><p>Produk favorit, dengan harga yang masuk akal.</p></div><button class="text-btn" data-action="nav" data-page="explore">Lihat semua${icon('arrow','small-icon')}</button></div>${categoryButtons()}<div class="products">${filteredProducts().slice(0,3).map(p=>productCard(p)).join('')||emptyProducts()}</div><div style="margin-top:21px" class="row between"><span class="total-count">${filteredProducts().length} produk pilihan · Harga ilustratif</span><button class="text-btn" data-action="nav" data-page="explore" style="font-size:10px">Jelajahi lebih banyak${icon('arrow','small-icon')}</button></div></section><aside class="right-column"><section class="side-panel"><div class="icon-heading">${icon('trending')}<h3>Lagi turun harga</h3><span class="pill green-pill" style="font-size:8px;margin-left:auto;padding:4px 6px">Pilihan</span></div>${[1,4].map(id=>{const p=product(id);return `<button class="insight-item" style="width:100%;text-align:left" data-action="history" data-id="${id}"><span class="insight-image"><img src="assets/${p.asset}.svg" alt=""></span><span><strong>${p.name}</strong><p>${money(p.history[0])} <span style="padding:0 2px">→</span> ${money(lowest(p))}</p><span class="discount">${icon('trending')}Turun ${money(p.history[0]-lowest(p))}</span></span></button>`;}).join('')}<button class="text-btn" data-action="nav" data-page="watchlist">Pantau produk favoritmu${icon('arrow','small-icon')}</button></section><section class="side-panel"><div class="icon-heading">${icon('card')}<h3>Kartumu, promomu.</h3></div><p style="font-size:10px;color:#92a197;line-height:1.8">Harga bisa lebih rendah dengan<br>metode pembayaran yang tepat.</p>${store.payment?`<div class="payment-preview"><div class="row"><span class="bank-logo"></span><span><span class="bank-name">${esc(store.payment.issuer)} Bank</span><br><small>${esc(store.payment.type)} •••• ${esc(store.payment.last4)}</small></span><span class="card-type">VISA</span></div></div><p class="payment-offer"><b>Diskon hingga 10%</b> di toko pilihan.<br>Cek promo yang cocok dengan kartumu.</p><button class="text-btn" data-action="compare" data-id="1" data-mode="personal">Lihat harga personal${icon('arrow','small-icon')}</button>`:`<p class="payment-offer">Tambahkan bank penerbit untuk melihat harga setelah promo.</p><button class="text-btn" data-action="add-payment">Tambahkan pembayaran${icon('plus','small-icon')}</button>`}</section><div class="tip-panel">${icon('bulb')}<div><strong>Tak harus beli hari ini.</strong><p>Simpan produk dan tentukan target harga. Buddy bantu kamu memantaunya.</p></div></div></aside></div><div class="partners-row"><span>Satu Buddy, banyak pilihan.</span><span class="partner amazon-word">amazon<span style="font-size:10px">⌣</span></span><span class="partner flipkart-word">Flipkart</span><span class="partner">blinkit</span><span class="partner zepto-word">zepto</span><span class="partner instamart-word">swiggy instamart</span></div>${footer()}`;}
function footer(){return `<footer class="footer-note"><span class="row">${icon('shield')}Hanya bank & 4 digit terakhir. Tidak menyimpan nomor kartu lengkap.</span><span>Rupiah · Data contoh, bukan harga live <button style="text-decoration:underline" data-action="scope">Detail</button></span></footer>`;}
function explore(){const list=filteredProducts();return `${heading('Temukan. Bandingkan. Hemat.','Semua toko dalam satu pandangan. Mulai dari produk yang kamu suka.',`<button class="btn btn-secondary" data-action="refresh-catalog">${icon('refresh','small-icon')}Perbarui</button>`)}${mobileSearch()}<div class="view-tools">${categoryButtons()}<select id="catalog-sort" aria-label="Urutkan produk"><option value="popular" ${catalogSort==='popular'?'selected':''}>Pilihan populer</option><option value="price" ${catalogSort==='price'?'selected':''}>Harga terendah</option><option value="savings" ${catalogSort==='savings'?'selected':''}>Hemat terbanyak</option></select></div><p class="search-label">${query?`Hasil untuk “${esc(query)}” · `:''}${list.length} produk ditemukan</p><div class="products watch-products">${list.map(p=>productCard(p)).join('')||emptyProducts()}</div>${footer()}`;}
function watchlist(){const saved=products.filter(p=>store.saved.includes(p.id));const reached=saved.filter(p=>store.thresholds[p.id]&&lowest(p)<=store.thresholds[p.id]).length;return `${heading('Simpan sekarang. Hemat nanti.','Produk incaranmu, tanpa perlu mengecek harga setiap hari.',`<button class="btn btn-secondary" data-action="nav" data-page="explore">${icon('plus','small-icon')}Tambah produk</button>`)}${saved.length?`<div class="watch-summary">${icon('bell')}<div><strong>${saved.length} produk dalam pantauan</strong><p>${reached?`${reached} produk mencapai target harga pada data demo.`:'Tentukan target harga untuk setiap produk incaranmu.'}</p></div><button class="btn btn-secondary btn-sm" data-action="notifications">Lihat notifikasi${icon('arrow','small-icon')}</button></div><div class="products watch-products">${saved.map(p=>productCard(p,true)).join('')}</div>`:`<div class="empty">${icon('heart')}<h3>Pantauanmu masih kosong</h3><p>Ketuk ikon hati pada produk favoritmu. Kembali ke sini untuk mengatur target harga.</p><button class="btn btn-primary" data-action="nav" data-page="explore">Jelajahi produk${icon('arrow','small-icon')}</button></div>`}${footer()}`;}
function payments(){const pay=store.payment;return `${heading('Kartumu punya kelebihan.','Simpan preferensi pembayaran untuk melihat promo yang relevan.',`<button class="btn btn-primary" data-action="add-payment">${icon(pay?'card':'plus','small-icon')}${pay?'Ubah pembayaran':'Tambah pembayaran'}</button>`)}<div class="settings-grid"><div><section class="settings-card"><h2>Metode pembayaran</h2><p>Gunakan bank penerbit kartu, bukan nomor kartu lengkap.</p>${pay?`<div class="saved-bank-card"><div class="row between"><div class="row"><span class="bank-logo"></span><strong>${esc(pay.issuer)} Bank</strong></div><span class="pill green-pill">Aktif</span></div><div class="card-number">•••• &nbsp; •••• &nbsp; •••• &nbsp; ${esc(pay.last4)}</div><div class="card-label">Kartu ${esc(pay.type)} · Preferensi demo</div><span class="card-type">VISA</span></div><div class="row between"><span class="row muted" style="font-size:10px">${icon('shield','small-icon')}Nomor lengkap tidak disimpan</span><button class="text-btn danger" style="font-size:10px" data-action="remove-payment">${icon('trash','small-icon')}Hapus</button></div>`:`<div class="empty" style="padding:40px 15px;margin-top:20px">${icon('card')}<h3>Belum ada pembayaran</h3><p>Tambahkan kartu, UPI, atau wallet untuk menyesuaikan pencarian promo.</p><button class="btn btn-soft" data-action="add-payment">Tambahkan pembayaran</button></div>`}<div class="scope-note"><strong>Privasi pada preview</strong><br>Preferensi disimpan di browser ini. Jangan masukkan informasi kartu nyata. Keystore dan enkripsi native belum terintegrasi.</div></section></div><section class="settings-card"><div class="row" style="gap:9px;margin-bottom:7px">${icon('tag')}<h2 style="margin:0">Promo yang cocok</h2></div><p>Contoh promo berdasarkan preferensi pembayaran.</p>${pay?`<div class="offer-list">${['amazon','flipkart','blinkit'].map((id,i)=>`<div class="offer-item">${platformLogo(id)}<div><strong>${i===2?'Cashback':'Diskon instan'} ${pay.type==='Kredit'||pay.type==='Debit'?(i===0?'10%':'5%'):'2%'}</strong><p>${platforms[id].name} · ${esc(pay.issuer)} ${esc(pay.type)}<br>${i===0?`Min. transaksi ${money(demoToIdr(5000))} · Maks. ${money(demoToIdr(2000))}`:i===1?`Min. transaksi ${money(demoToIdr(3000))} · Maks. ${money(demoToIdr(1500))}`:`Min. transaksi ${money(demoToIdr(500))} · Maks. ${money(demoToIdr(100))}`}</p><span class="pill orange-pill">Promo ilustratif</span></div></div>`).join('')}</div><button class="btn btn-soft" style="width:100%;margin-top:20px" data-action="compare" data-id="1" data-mode="personal">Bandingkan harga personal${icon('arrow','small-icon')}</button>`:`<div class="scope-note">Tambahkan metode pembayaran untuk melihat promo personal.</div>`}</section></div>${footer()}`;}
function settingToggle(key,title,description){return `<div class="setting-row"><div><strong>${title}</strong><p>${description}</p></div><button class="switch ${store.settings[key]?'on':''}" role="switch" aria-checked="${store.settings[key]}" aria-label="${title}" data-action="setting" data-key="${key}"></button></div>`;}
function settings(){return `${heading('Sesuai caramu belanja.','Atur notifikasi, privasi, dan profil USDpedia.')}<div class="settings-hero">${buddy()}<div><h2>${esc(store.name)}, Buddy-mu siap.</h2><p>Preferensi tersimpan di browser ini, bukan di server.</p></div><button class="btn btn-secondary" style="margin-left:auto" data-action="profile">${icon('user','small-icon')}Ubah profil</button></div><div class="settings-grid"><div><section class="settings-card"><h2>Notifikasi</h2><p>Pilih informasi yang ingin kamu lihat di aplikasi.</p>${settingToggle('priceAlerts','Harga turun','Tampilkan notifikasi saat target harga demo tercapai.')}${settingToggle('stockAlerts','Produk kembali tersedia','Simpan permintaan pemberitahuan stok.')}${settingToggle('personalDeals','Promo pembayaran','Tampilkan promo yang sesuai dengan kartumu.')}<div class="scope-note">Notifikasi dalam preview bersifat simulasi. Push Android dan pengecekan otomatis di latar belakang memerlukan aplikasi native dan backend.</div></section></div><div><section class="settings-card"><h2>Privasi & data</h2><p>Kamu memegang kendali atas preferensimu.</p>${settingToggle('analytics','Berbagi analitik penggunaan','Pilihan persetujuan saja; preview ini tidak mengirim analitik.')}<div class="setting-row"><div><strong>Data yang disimpan</strong><p>Nama, bank, empat digit terakhir, pantauan, dan preferensi.</p></div><button class="text-btn" data-action="privacy">Detail${icon('chevron','small-icon')}</button></div><div class="setting-row"><div><strong>Hapus data lokal</strong><p>Hapus profil, pembayaran, pantauan, dan laporan dari browser ini.</p></div><button class="text-btn danger" data-action="delete-data">Hapus${icon('trash','small-icon')}</button></div></section><section class="settings-card"><h2>Kode pos pengiriman</h2><p>Platform dalam PRD berbasis India. Harga demo ditampilkan dalam rupiah (IDR), bukan harga live Indonesia.</p><button class="btn btn-secondary" style="margin-top:18px" data-action="location">${icon('location','small-icon')}India · ${esc(store.postal)}${icon('chevron','small-icon')}</button></section></div></div>${footer()}`;}
function help(){return `${heading('Ada yang ingin ditanyakan?','Kenali cara Buddy bekerja dan kirim masukan untuk pengalaman yang lebih baik.')}<div class="settings-grid"><section class="settings-card"><h2>Pertanyaan umum</h2>${[
['Apakah harga ini sudah live?','Belum. Preview web memakai data contoh agar seluruh alur bisa dicoba. Harga, ulasan, ketersediaan, dan promo bukan informasi pasar saat ini. Integrasi API/scraping dan cache 30–60 menit perlu dihubungkan pada versi produksi.'],
['Apa bedanya tiga mode perbandingan?','Harga standar membandingkan harga produk. Harga personal menghitung promo dari bank atau metode pembayaran pilihanmu. Detail lengkap menambahkan pengiriman, ulasan, aktivitas, kebijakan retur, serta stok. Ongkir ditampilkan terpisah pada mode standar/personal.'],
['Apakah Buddy bisa muncul di atas aplikasi lain?','Overlay lintas aplikasi hanya dapat dijalankan di aplikasi Android native dengan izin sistem. Tombol Buddy pada preview ini hanya bekerja di dalam halaman web ini.'],
['Bagaimana harga rupiah ini dihitung?','Seluruh nilai contoh—harga produk, ongkir, promo, dan riwayat—disesuaikan ke rupiah menggunakan faktor demo tetap 190. Ini bukan kurs live atau harga toko Indonesia. Platform dan bank tetap mengikuti PRD. Target harga lama ikut dikonversi sekali, sedangkan target baru diisi langsung dalam rupiah.'],
['Apakah data kartuku aman?','Preview hanya menerima bank penerbit dan empat digit terakhir; tidak meminta nomor lengkap, CVV, atau tanggal kedaluwarsa. Preferensi browser ini tidak terenkripsi dan tidak dipakai untuk transaksi. Aplikasi produksi membutuhkan Android Keystore dan penilaian kepatuhan PCI.'],
['Bagaimana cara memasang target harga?','Simpan produk dengan ikon hati, buka Daftar pantauan, lalu pilih Atur. Masukkan target harga. Notifikasi demo akan muncul jika harga contoh sama atau lebih rendah dari target.']
].map(([q,a])=>`<details class="faq-item"><summary>${q}</summary><p>${a}</p></details>`).join('')}<button class="text-btn" style="margin-top:18px" data-action="onboard">${icon('spark','small-icon')}Mulai tur singkat</button></section><section class="settings-card"><h2>Bantu Buddy jadi lebih baik</h2><p>Kirim masukan atau laporkan masalah. Pada preview, laporan tersimpan secara lokal.</p><form id="feedback-form" class="report-form"><label class="form-label" for="feedback-type">Jenis masukan</label><select class="field" id="feedback-type"><option>Ide & saran</option><option>Laporan bug</option><option>Masalah harga</option></select><label class="form-label" for="feedback-message">Ceritakan detailnya</label><textarea class="field" id="feedback-message" required minlength="10" maxlength="1500" placeholder="Apa yang bisa kami perbaiki? (minimal 10 karakter)"></textarea><button class="btn btn-primary" type="submit">Simpan masukan${icon('arrow','small-icon')}</button></form><p class="field-hint">${store.reports.length} laporan tersimpan di browser ini.</p></section></div>${footer()}`;}
function renderMain(){const views={home,explore,watchlist,payments,settings,help};$('#main-content').innerHTML=views[page]();}
function navigate(next){page=next;query='';category='Semua';fabOpen=false;render();window.scrollTo({top:0,behavior:'instant'});}
function renderFab(){const menus=[['standard','compare','Bandingkan harga','Harga standar antar toko'],['personal','card','Harga personal','Termasuk promo pembayaran'],['full','chart','Detail lengkap','Harga, pengiriman, ulasan & lainnya']];$('#fab-root').innerHTML=`${fabOpen?`<div class="fab-menu"><p>Buddy bantu apa hari ini?</p>${menus.map(([mode,i,title,sub])=>`<button data-action="compare" data-id="${currentProduct}" data-mode="${mode}">${icon(i)}<span>${title}<small>${sub}</small></span></button>`).join('')}<button data-action="nav" data-page="settings">${icon('settings')}Pengaturan</button></div>`:''}<button class="fab" data-action="fab" aria-label="${fabOpen?'Tutup':'Buka'} asisten Buddy" aria-expanded="${fabOpen}">${fabOpen?icon('close'):buddy(true)}</button>`;}
function showDialog(content,type='center'){
  if(!$('#dialog-root').firstChild)lastFocused=document.activeElement;
  $('#dialog-root').innerHTML=`<div class="dialog-backdrop ${type==='drawer'?'side-backdrop':''}" data-action="close-dialog"></div><section class="dialog ${type}" role="dialog" aria-modal="true" aria-labelledby="dialog-title" tabindex="-1"><button class="icon-btn dialog-close" data-action="close-dialog" aria-label="Tutup">${icon('close')}</button>${content}</section>`;
  document.body.style.overflow='hidden';requestAnimationFrame(()=>$('.dialog').focus({preventScroll:true}));
}
function closeDialog(){ $('#dialog-root').innerHTML='';document.body.style.overflow='';if(lastFocused&&lastFocused.isConnected)lastFocused.focus({preventScroll:true}); }
function offerDeal(o){if(!store.payment||!store.settings.personalDeals)return {discount:0,label:'Tidak ada promo aktif'};const pay=store.payment;let rate=0,cap=0,min=0;if(pay.type==='UPI'||pay.type==='Wallet'){rate=.02;cap=o.platform==='amazon'?200:100;min=500;}else{const rates={HDFC:.10,ICICI:.08,SBI:.07,Axis:.06};const base=rates[pay.issuer]||.05;if(o.platform==='amazon'){rate=base;cap=2000;min=5000;}if(o.platform==='flipkart'){rate=.05;cap=1500;min=3000;}if(['blinkit','zepto','instamart'].includes(o.platform)){rate=.05;cap=100;min=500;}}min=demoToIdr(min);cap=demoToIdr(cap);const discount=o.price>=min?Math.min(Math.round(o.price*rate),cap):0;return {discount,label:discount?`${Math.round(rate*100)}% ${pay.issuer} ${pay.type==='UPI'||pay.type==='Wallet'?'cashback':'discount'}`:`Min. transaksi ${money(min)} belum tercapai`};}
function offerFinal(o){return o.price-(compareMode==='personal'?offerDeal(o).discount:0);}
function deliveryMinutes(s){if(s==='Besok')return 1440;if(s.includes('hari'))return parseInt(s)*1440;return parseInt(s);}
function sortedOffers(p){let list=[...p.offers];if(compareSort==='savings')list.sort((a,b)=>(p.mrp-offerFinal(b))-(p.mrp-offerFinal(a)));else if(compareSort==='delivery')list.sort((a,b)=>deliveryMinutes(a.delivery)-deliveryMinutes(b.delivery));else if(compareSort==='platform')list.sort((a,b)=>platforms[a.platform].name.localeCompare(platforms[b.platform].name));else list.sort((a,b)=>offerFinal(a)-offerFinal(b));return list;}
function compare(id,mode='standard'){currentProduct=Number(id);compareMode=mode;compareSort='price';selectedPlatforms=product(id).offers.map(o=>o.platform);fabOpen=false;renderFab();renderComparison();}
function modeTabs(){return `<div class="mode-tabs" role="tablist" aria-label="Mode perbandingan">${[['standard','compare','Harga standar'],['personal','card','Personal'],['full','chart','Lengkap']].map(([mode,i,t])=>`<button class="${compareMode===mode?'active':''}" role="tab" aria-selected="${compareMode===mode}" data-action="mode" data-mode="${mode}">${icon(i)}${t}</button>`).join('')}</div>`;}
function renderComparison(){const p=product(currentProduct);if(compareMode==='full'){renderComprehensive(p);return;}const offers=sortedOffers(p);const best=Math.min(...p.offers.filter(o=>o.stock).map(offerFinal));showDialog(`<header class="dialog-head"><p class="eyebrow">USDpedia COMPARE</p><h2 id="dialog-title">Harga terbaik, di satu tempat.</h2><p>Produk sama. Pilihan lebih jelas. Semua data di bawah adalah demo.</p></header><div class="compare-product"><img src="assets/${p.asset}.svg" alt="${p.name}"><div><h3>${p.name}</h3><p>${p.spec}</p><div class="rating-line"><span class="star">★</span><b>${p.rating}</b> · ${p.reviews} ulasan</div></div></div>${modeTabs()}${compareMode==='personal'?`<div class="personal-payment">${icon('card')}<span>${store.payment?`${esc(store.payment.issuer)} ${esc(store.payment.type)} •••• ${esc(store.payment.last4)}`:'Belum ada metode pembayaran'}</span><button class="text-btn" data-action="add-payment">${store.payment?'Ubah':'Tambah'}</button></div>${!store.settings.personalDeals?'<p class="field-hint" style="margin:12px 24px 0">Promo personal dinonaktifkan di Pengaturan.</p>':''}`:''}<div class="comparison-controls"><strong>${offers.length} toko dibandingkan</strong><select id="compare-sort" aria-label="Urutkan penawaran">${[['price','Harga terendah'],['savings','Hemat terbanyak'],['delivery','Pengiriman tercepat'],['platform','Nama platform']].map(([v,t])=>`<option value="${v}" ${compareSort===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="offer-results">${offers.map(o=>{const final=offerFinal(o),deal=offerDeal(o),isBest=o.stock&&final===best;return `<article class="offer-result ${isBest?'best':''}">${isBest?`<div class="best-label">${icon('spark','small-icon')}HARGA TERBAIK YANG TERSEDIA</div>`:''}<div class="row">${platformLogo(o.platform)}<div><div class="platform-name">${platforms[o.platform].name}</div><div class="stock-label ${!o.stock?'out':''}">${o.stock?'● Tersedia':'○ Stok habis'}</div></div><div class="offer-price">${compareMode==='personal'&&deal.discount?`<del>${money(o.price)}</del>`:''}<strong>${money(final)}</strong></div></div>${compareMode==='personal'?`<div class="deal-line">${icon('tag','small-icon')}${deal.label}${deal.discount?` · Hemat ${money(deal.discount)}`:''}</div>`:''}<div class="offer-details">${icon('truck','small-icon')}${o.stock?`Tiba ${o.delivery.toLowerCase()}`:`Restok ${o.restock}`}&nbsp; · &nbsp;${o.shipping?'Ongkir '+money(o.shipping):'Gratis ongkir'}</div><div class="offer-actions"><span>Hemat ${money(p.mrp-final)} dari MRP</span><button class="btn ${o.stock?(isBest?'btn-primary':'btn-soft'):'btn-secondary'}" data-action="${o.stock?'buy':'stock-alert'}" data-id="${p.id}" data-platform="${o.platform}">${o.stock?'Beli sekarang':store.alerts.some(a=>a.id===p.id&&a.platform===o.platform)?'Pantauan aktif':'Kabari saya'}${icon(o.stock?'external':'bell','small-icon')}</button></div></article>`;}).join('')}</div><footer class="drawer-footer"><span>Data demo · ${lastUpdated.toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'})} · Ongkir terpisah</span><button class="text-btn" data-action="refresh-compare">${icon('refresh','small-icon')}Perbarui</button></footer>`,'drawer');}
function detailTile(o,content){return `<div class="detail-tile"><div class="row">${platformLogo(o.platform)}<span class="platform-name">${platforms[o.platform].name}</span>${!o.stock?'<span class="pill gray-pill" style="margin-left:auto;font-size:8px;padding:4px 6px">Stok habis</span>':''}</div>${content}</div>`;}
function renderComprehensive(p){const chosen=p.offers.filter(o=>selectedPlatforms.includes(o.platform));const sections=[
  ['tag','Harga & penghematan',o=>{const d=offerDeal(o);return `<span class="tile-price">${money(o.price-d.discount)}</span>${d.discount?`<del>${money(o.price)}</del>`:''}<p>${d.label}</p><p class="tile-save">Hemat ${money(p.mrp-o.price+d.discount)} dari MRP ${money(p.mrp)}</p><p>Total dengan ongkir: <b>${money(o.price-d.discount+o.shipping)}</b></p>`;}],
  ['truck','Pengiriman',o=>`<div class="value">${o.stock?'Tiba '+o.delivery.toLowerCase():'Pengiriman belum tersedia'}</div><p>${o.shipping?'Biaya pengiriman '+money(o.shipping):'Gratis ongkir'}</p><span class="pill green-pill">${o.prime?'Prime eligible':o.delivery.includes('menit')?'Express delivery':'Pengiriman standar'}</span>`],
  ['star','Rating & kualitas',o=>`<div class="value"><span style="color:#d9aa4e">★</span> ${o.rating} / 5</div><p>${o.reviewCount.toLocaleString('id-ID')} ulasan pembeli</p><span class="pill green-pill">Pembelian terverifikasi</span>`],
  ['trending','Aktivitas 30 hari',o=>`<div class="value">${o.sold.toLocaleString('id-ID')} unit terjual</div><p>${o.trend?'↗ Sedang diminati':'— Permintaan stabil'}</p><span class="pill orange-pill">${o.sentiment}</span>`],
  ['return','Retur & pengembalian dana',o=>`<div class="value">${o.returnDays?`Retur ${o.returnDays} hari`:'Tidak dapat diretur'}</div><p>Refund: ${o.refund}<br>${o.replacement?'Penggantian untuk produk cacat tersedia.':'Penggantian tidak tersedia.'}</p><p>${o.returnDays?'Kemasan asli dan bukti pembelian diperlukan.':'Laporkan barang rusak melalui bantuan toko.'}</p>`],
  ['box','Stok & penjual',o=>`<div class="value ${o.stock?'green':''}">${o.stock?'Tersedia':'Stok habis'}</div><p>Penjual: ${o.seller}<br>${o.stock?'Siap dikirim sesuai estimasi.':'Estimasi restok: '+o.restock}</p><button class="btn ${o.stock?'btn-soft':'btn-secondary'} btn-sm" style="margin-top:10px" data-action="${o.stock?'buy':'stock-alert'}" data-id="${p.id}" data-platform="${o.platform}">${o.stock?'Beli sekarang':'Kabari saya'}${icon(o.stock?'external':'bell','small-icon')}</button>`]
];showDialog(`<header class="dialog-head"><p class="eyebrow">GAMBARAN YANG LEBIH UTUH</p><h2 id="dialog-title">Bukan cuma soal harga.</h2><p>Bandingkan 6 hal penting sebelum memutuskan. Data & kebijakan ilustratif.</p></header>${modeTabs()}<div class="comprehensive-body"><div class="comprehensive-intro"><img src="assets/${p.asset}.svg" alt="${p.name}"><div><h3>${p.name}</h3><p>${p.spec}</p></div><button class="btn btn-secondary btn-sm" data-action="alert" data-id="${p.id}">${icon('bell','small-icon')}Atur target harga</button></div><div class="platform-filters" aria-label="Pilih toko yang dibandingkan">${p.offers.map(o=>`<button class="platform-filter ${selectedPlatforms.includes(o.platform)?'selected':''}" aria-pressed="${selectedPlatforms.includes(o.platform)}" data-action="platform-filter" data-platform="${o.platform}">${platformLogo(o.platform)}${platforms[o.platform].name}${selectedPlatforms.includes(o.platform)?icon('check','small-icon'):''}</button>`).join('')}</div>${sections.map(([i,title,fn])=>`<section class="detail-section"><h3>${icon(i)}${title}</h3><div class="detail-columns">${chosen.map(o=>detailTile(o,fn(o))).join('')}</div></section>`).join('')}</div><footer class="drawer-footer"><span>Data demo · Cache produksi: 60 menit · Harga termasuk promo aktif</span><button class="text-btn" data-action="refresh-compare">${icon('refresh','small-icon')}Perbarui</button></footer>`,'comprehensive');}
function paymentDialog(){formPaymentType=store.payment?.type||'Kredit';renderPaymentForm();}
function renderPaymentForm(){const pay=store.payment;showDialog(`<div class="modal-icon">${icon('card')}</div><h2 class="modal-title" id="dialog-title">Promo dimulai dari kartumu.</h2><p class="modal-description">Pilih metode pembayaran. Tidak perlu nomor lengkap, CVV, atau tanggal kedaluwarsa.</p><form id="payment-form"><label class="form-label">Metode pembayaran</label><div class="payment-types">${['Kredit','Debit','UPI','Wallet'].map(t=>`<button type="button" class="payment-type ${formPaymentType===t?'selected':''}" data-action="payment-type" data-type="${t}">${t}</button>`).join('')}</div><label class="form-label" for="payment-issuer">${['UPI','Wallet'].includes(formPaymentType)?'Penyedia':'Bank penerbit'}</label><select class="field" id="payment-issuer">${(formPaymentType==='UPI'?['Google Pay','PhonePe','Paytm']:formPaymentType==='Wallet'?['Paytm','Amazon Pay']:['HDFC','ICICI','SBI','Axis']).map(b=>`<option ${pay?.issuer===b?'selected':''}>${b}</option>`).join('')}</select>${!['UPI','Wallet'].includes(formPaymentType)?`<label class="form-label" for="payment-last4">Empat digit terakhir (contoh saja)</label><input class="field" id="payment-last4" inputmode="numeric" pattern="[0-9]{4}" minlength="4" maxlength="4" required value="${esc(pay?.last4||'')}" placeholder="Contoh: 4242"><p class="field-hint">Gunakan angka contoh. Kami tidak meminta data kartu nyata.</p>`:''}<div class="scope-note">${icon('shield','small-icon')}Preferensi disimpan di browser ini, belum menggunakan enkripsi Android Keystore.</div><div class="modal-actions"><button class="btn btn-secondary" type="button" data-action="close-dialog">Batal</button><button class="btn btn-primary" type="submit">Simpan preferensi${icon('check','small-icon')}</button></div></form>`);}
function alertDialog(id){const p=product(id);currentProduct=p.id;showDialog(`<div class="modal-icon">${icon('bell')}</div><h2 class="modal-title" id="dialog-title">Harga pas, baru gas.</h2><p class="modal-description">Tentukan target untuk ${p.name}. Harga saat ini pada data demo: <b>${money(lowest(p))}</b>.</p><form id="alert-form" data-id="${p.id}"><label class="form-label" for="target-price">Target harga (Rupiah)</label><div class="alert-price">Rp<input id="target-price" type="number" min="1" max="999999999" step="1" required value="${store.thresholds[p.id]||Math.round(lowest(p)*.9)}" aria-label="Target harga dalam rupiah"></div><p class="field-hint">Produk otomatis ditambahkan ke daftar pantauanmu.</p><div class="scope-note">Notifikasi di dalam aplikasi ini adalah simulasi. Pengecekan otomatis harga live belum terhubung.</div><div class="modal-actions"><button class="btn btn-secondary" type="button" data-action="close-dialog">Batal</button><button class="btn btn-primary" type="submit">Simpan target${icon('check','small-icon')}</button></div></form>`);}
function notifications(){const targets=products.filter(p=>store.thresholds[p.id]&&lowest(p)<=store.thresholds[p.id]);showDialog(`<div class="modal-icon">${icon('bell')}</div><h2 class="modal-title" id="dialog-title">Kabar dari Buddy.</h2><p class="modal-description">Notifikasi dan permintaan pantauan di browser ini.</p>${store.settings.priceAlerts?targets.map(p=>`<button class="notification-item" style="width:100%;text-align:left" data-action="compare" data-id="${p.id}" data-mode="standard">${icon('trending')}<span><strong>${p.name} mencapai target</strong><p>Harga demo ${money(lowest(p))}, lebih rendah atau sama dengan target ${money(store.thresholds[p.id])}.</p><small>Buka perbandingan harga →</small></span></button>`).join(''):''}${store.alerts.map(a=>`<div class="notification-item">${icon('box')}<div><strong>Menunggu stok ${product(a.id).name}</strong><p>Pantauan ${platforms[a.platform].name} tersimpan. Stok demo belum berubah.</p><small>Simulasi · Pengecekan live belum aktif</small></div></div>`).join('')}${!targets.length&&!store.alerts.length?`<div class="empty" style="border:0;padding:25px 0">${icon('check')}<h3>Belum ada kabar baru</h3><p>Atur target harga atau pantau produk yang stoknya habis.</p><button class="btn btn-soft" data-action="goto-watchlist">Buka daftar pantauan</button></div>`:''}${!store.settings.priceAlerts?'<div class="scope-note">Notifikasi harga dimatikan. Aktifkan kembali di Pengaturan.</div>':''}`);}
function history(id){const p=product(id),h=p.history,max=Math.max(...h),min=Math.min(...h),range=max-min||1;const pts=h.map((v,i)=>[i*50,80-((v-min)/range)*60]);const path=pts.map(([x,y],i)=>`${i?'L':'M'}${x},${y}`).join(' ');showDialog(`<div class="modal-icon">${icon('trending')}</div><h2 class="modal-title" id="dialog-title">Turun harga. Naik peluang.</h2><p class="modal-description">${p.name} · Riwayat harga contoh selama 7 hari.</p><div class="history-panel"><div class="row between"><h3>Harga terendah antar toko</h3><span class="pill green-pill">−${money(max-min)}</span></div><svg viewBox="-5 0 310 100" role="img" aria-label="Harga turun dari ${money(max)} ke ${money(min)}"><defs><linearGradient id="history-fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#94d2af" stop-opacity=".4"/><stop offset="1" stop-color="#94d2af" stop-opacity="0"/></linearGradient></defs><path d="M0 90H300M0 50H300M0 10H300" stroke="#e1ece3" stroke-dasharray="3 4"/><path d="${path}L300 100L0 100Z" fill="url(#history-fill)"/><path d="${path}" stroke="#087f69" stroke-width="3" fill="none" stroke-linejoin="round"/>${pts.map(([x,y])=>`<circle cx="${x}" cy="${y}" r="3.5" fill="#fff" stroke="#087f69" stroke-width="2"/>`).join('')}</svg><div class="history-labels"><span>7 Nov · ${money(max)}</span><span>13 Nov · ${money(min)}</span></div></div><div class="modal-actions"><button class="btn btn-secondary" data-action="alert" data-id="${p.id}">${icon('bell','small-icon')}Atur target</button><button class="btn btn-primary" data-action="compare" data-id="${p.id}" data-mode="standard">Bandingkan${icon('arrow','small-icon')}</button></div>`);}
function buy(id,platform){const p=product(id),o=p.offers.find(x=>x.platform===platform),d=compareMode==='personal'||compareMode==='full'?offerDeal(o).discount:0;showDialog(`<div class="modal-icon">${icon('external')}</div><h2 class="modal-title" id="dialog-title">Pilihanmu: ${platforms[platform].name}.</h2><p class="modal-description">Di aplikasi produksi, kamu akan diarahkan ke halaman produk di toko. Preview ini tidak melakukan transaksi atau membuka tautan produk.</p><div class="checkout-product"><img src="assets/${p.asset}.svg" alt="${p.name}"><div><strong>${p.name}</strong><p>${platforms[platform].name} · Tiba ${o.delivery.toLowerCase()}</p><div class="price">${money(o.price-d)}</div></div></div><div class="price-example"><div class="row"><span>Harga produk</span><span>${money(o.price)}</span></div>${d?`<div class="row"><span>Promo pembayaran</span><span class="green">−${money(d)}</span></div>`:''}<div class="row"><span>Ongkir</span><span>${o.shipping?money(o.shipping):'Gratis'}</span></div><div class="row"><span>Total ilustratif</span><span>${money(o.price-d+o.shipping)}</span></div></div><div class="modal-actions"><button class="btn btn-secondary" data-action="return-compare">Kembali</button><button class="btn btn-primary" data-action="close-dialog">Mengerti${icon('check','small-icon')}</button></div>`);}
function profile(){showDialog(`<div class="modal-icon">${icon('user')}</div><h2 class="modal-title" id="dialog-title">Buddy mengenalmu sebagai…</h2><p class="modal-description">Nama ini hanya digunakan untuk sapaan di aplikasi.</p><form id="profile-form"><label class="form-label" for="profile-name">Nama panggilan</label><input class="field" id="profile-name" required minlength="2" maxlength="30" value="${esc(store.name)}" autocomplete="given-name"><div class="modal-actions"><button class="btn btn-secondary" type="button" data-action="close-dialog">Batal</button><button class="btn btn-primary" type="submit">Simpan nama</button></div></form>`);}
function locationDialog(){showDialog(`<div class="modal-icon">${icon('location')}</div><h2 class="modal-title" id="dialog-title">Belanja ke mana?</h2><p class="modal-description">Masukkan kode pos India. Pada preview, pilihan ini belum mengubah estimasi pengiriman.</p><form id="location-form"><label class="form-label" for="postal-code">Kode pos (6 digit)</label><input class="field" id="postal-code" required pattern="[1-9][0-9]{5}" maxlength="6" minlength="6" inputmode="numeric" value="${esc(store.postal)}"><p class="field-hint">Contoh: 560001 untuk Bengaluru, India.</p><div class="modal-actions"><button class="btn btn-secondary" type="button" data-action="close-dialog">Batal</button><button class="btn btn-primary" type="submit">Simpan lokasi</button></div></form>`);}
function privacy(scope=false){showDialog(`<div class="modal-icon">${icon(scope?'info':'shield')}</div><h2 class="modal-title" id="dialog-title">${scope?'Yang bisa dicoba sekarang.':'Privasimu tetap milikmu.'}</h2><p class="modal-description">USDpedia adalah preview web interaktif berdasarkan PRD aplikasi Android.</p>${scope?`<ul class="privacy-list"><li><b>Berfungsi:</b> pencarian, filter, 3 mode perbandingan, perhitungan promo, pantauan, target harga, preferensi, dan alur onboarding.</li><li><b>Data contoh:</b> harga, stok, pengiriman, ulasan, promo, tren, dan kebijakan toko.</li><li><b>Belum terhubung:</b> OAuth, scraping/API, pembayaran, affiliate deep links, push, background refresh, PostgreSQL/Redis, dan overlay lintas aplikasi Android.</li><li><b>Penyimpanan:</b> localStorage browser, bukan database server atau Android Keystore.</li></ul>`:`<ul class="privacy-list"><li>Nama, kode pos, preferensi bank, 4 digit terakhir, pantauan, dan laporan tersimpan lokal di browser.</li><li>Tidak meminta PAN, CVV, PIN, atau tanggal kedaluwarsa. Gunakan data contoh saja.</li><li>Tidak mengirim data ke toko atau layanan analitik. Font dimuat dari Google Fonts.</li><li>Hapus data kapan saja dari Pengaturan. Penyimpanan browser preview tidak terenkripsi.</li></ul>`}<button class="btn btn-primary" style="width:100%" data-action="close-dialog">Mengerti</button>`);}
function onboarding(){if(onboardStep===0){showDialog(`<div class="onboarding-art">${buddy()}<span class="pill green-pill">Hey, shopping buddy!</span></div><p class="eyebrow green">KENALAN DULU, YUK</p><h2 class="modal-title" id="dialog-title">Belanja lebih tenang.<br>Buddy urus bandingannya.</h2><p class="modal-description">Tiga cara untuk memilih dengan yakin: harga standar, promo personal, dan perbandingan lengkap.</p><div class="step-dots"><span class="active"></span><span></span><span></span><span></span></div><div class="modal-actions"><button class="btn btn-secondary" data-action="close-dialog">Nanti saja</button><button class="btn btn-primary" data-action="onboard-next">Mulai${icon('arrow','small-icon')}</button></div>`);}
else if(onboardStep===1){showDialog(`<div class="modal-icon">${icon('shield')}</div><h2 class="modal-title" id="dialog-title">Bantu Buddy membantumu.</h2><p class="modal-description">Di Android, izin sistem diperlukan untuk asisten di atas aplikasi. Di preview, kamu hanya mengatur preferensi.</p><div class="permission-list">${settingToggle('priceAlerts','Notifikasi harga','Simpan preferensi notifikasi dalam aplikasi.')}${settingToggle('stockAlerts','Notifikasi stok','Simpan preferensi pemberitahuan stok.')}</div><div class="permission-note">Izin Accessibility/overlay dan storage Android tidak bisa diminta oleh preview web. Tidak ada izin sistem yang diaktifkan.</div><div class="step-dots"><span></span><span class="active"></span><span></span><span></span></div><div class="modal-actions"><button class="btn btn-secondary" data-action="onboard-back">Kembali</button><button class="btn btn-primary" data-action="onboard-next">Lanjut${icon('arrow','small-icon')}</button></div>`);}
else if(onboardStep===2){showDialog(`<div class="modal-icon">${icon('card')}</div><h2 class="modal-title" id="dialog-title">Promo yang sesuai denganmu.</h2><p class="modal-description">Pilih bank untuk mencoba harga personal. Tidak ada informasi kartu lengkap yang diminta.</p><label class="form-label" for="onboard-bank">Bank penerbit</label><select class="field" id="onboard-bank">${['HDFC','ICICI','SBI','Axis'].map(b=>`<option ${store.payment?.issuer===b?'selected':''}>${b}</option>`).join('')}</select><p class="field-hint">Mode onboarding menyimpan preferensi kartu kredit demo •••• 4242.</p><div class="step-dots"><span></span><span></span><span class="active"></span><span></span></div><div class="modal-actions"><button class="btn btn-secondary" data-action="onboard-skip-payment">Lewati</button><button class="btn btn-primary" data-action="onboard-save-payment">Simpan & lanjut</button></div>`);}
else{showDialog(`<div class="onboarding-art" style="height:130px">${buddy()}<span class="pill green-pill">Siap jadi lebih hemat.</span></div><h2 class="modal-title" id="dialog-title">Satu tombol. Banyak jawaban.</h2><p class="modal-description">Tombol Buddy di kanan bawah membuka tiga mode perbandingan. Ikon hati menyimpan produk. Di Daftar pantauan, atur target hargamu.</p><div class="step-dots"><span></span><span></span><span></span><span class="active"></span></div><div class="modal-actions"><button class="btn btn-primary" data-action="onboard-finish">Coba Buddy sekarang${icon('arrow','small-icon')}</button></div>`);}}
function toggleSave(id){id=Number(id);const exists=store.saved.includes(id);store.saved=exists?store.saved.filter(x=>x!==id):[...store.saved,id];if(exists)delete store.thresholds[id];persist();render();toast(exists?'Produk dihapus dari pantauan.':'Produk disimpan. Atur target di Daftar pantauan.');}
function confirmDelete(){showDialog(`<div class="modal-icon">${icon('trash')}</div><h2 class="modal-title" id="dialog-title">Hapus semua data lokal?</h2><p class="modal-description">Profil, pembayaran, pantauan, target, dan laporan akan dihapus dari browser ini. Tindakan ini tidak dapat dibatalkan.</p><div class="modal-actions"><button class="btn btn-secondary" data-action="close-dialog">Batal</button><button class="btn btn-primary" style="background:#b76450" data-action="confirm-delete">Hapus data</button></div>`);}
document.addEventListener('click',event=>{
 const button=event.target.closest('[data-action]');if(!button)return;const a=button.dataset.action,id=button.dataset.id;
 if(a==='nav'){closeDialog();navigate(button.dataset.page);}
 else if(a==='category'){category=button.dataset.category;renderMain();}
 else if(a==='save')toggleSave(id);
 else if(a==='compare')compare(id,button.dataset.mode);
 else if(a==='fab'){fabOpen=!fabOpen;renderFab();}
 else if(a==='close-dialog')closeDialog();
 else if(a==='mode'){compareMode=button.dataset.mode;renderComparison();}
 else if(a==='platform-filter'){const pl=button.dataset.platform;if(selectedPlatforms.includes(pl)){if(selectedPlatforms.length===1){toast('Pilih setidaknya satu toko untuk perbandingan.');return;}selectedPlatforms=selectedPlatforms.filter(x=>x!==pl);}else selectedPlatforms.push(pl);renderComparison();}
 else if(a==='refresh-compare'){lastUpdated=new Date();renderComparison();toast('Tampilan data demo diperbarui. Harga tidak diambil dari toko.');}
 else if(a==='refresh-catalog'){lastUpdated=new Date();renderMain();toast('Katalog demo diperbarui. Belum terhubung ke harga live.');}
 else if(a==='add-payment')paymentDialog();
 else if(a==='payment-type'){formPaymentType=button.dataset.type;renderPaymentForm();}
 else if(a==='remove-payment'){showDialog(`<div class="modal-icon">${icon('card')}</div><h2 class="modal-title" id="dialog-title">Hapus preferensi pembayaran?</h2><p class="modal-description">Promo personal tidak akan dihitung sampai kamu menambahkan metode pembayaran lagi.</p><div class="modal-actions"><button class="btn btn-secondary" data-action="close-dialog">Batal</button><button class="btn btn-primary" data-action="confirm-remove-payment">Hapus preferensi</button></div>`);}
 else if(a==='confirm-remove-payment'){store.payment=null;persist();closeDialog();render();toast('Preferensi pembayaran dihapus.');}
 else if(a==='alert')alertDialog(id);
 else if(a==='notifications')notifications();
 else if(a==='goto-watchlist'){closeDialog();navigate('watchlist');}
 else if(a==='history')history(id);
 else if(a==='buy')buy(id,button.dataset.platform);
 else if(a==='return-compare')renderComparison();
 else if(a==='stock-alert'){const pl=button.dataset.platform;if(!store.alerts.some(x=>x.id===Number(id)&&x.platform===pl)){store.alerts.push({id:Number(id),platform:pl});if(!store.saved.includes(Number(id)))store.saved.push(Number(id));persist();render();renderComparison();toast('Pantauan stok disimpan. Pengecekan live belum aktif.');}else toast('Produk ini sudah dipantau. Lihat detail di Notifikasi.');}
 else if(a==='setting'){store.settings[button.dataset.key]=!store.settings[button.dataset.key];persist();button.classList.toggle('on',store.settings[button.dataset.key]);button.setAttribute('aria-checked',String(store.settings[button.dataset.key]));}
 else if(a==='profile')profile();
 else if(a==='location')locationDialog();
 else if(a==='privacy')privacy();
 else if(a==='scope')privacy(true);
 else if(a==='delete-data')confirmDelete();
 else if(a==='confirm-delete'){store=structuredClone(defaultStore);store.name='Teman';store.saved=[];store.payment=null;store.thresholds={};store.alerts=[];store.reports=[];try{localStorage.removeItem('buybuddy-v1');}catch{}persist();closeDialog();render();toast('Data lama dihapus. Profil kosong siap digunakan.');}
 else if(a==='reset-search'){query='';category='Semua';render();}
 else if(a==='menu'){$('.sidebar').classList.toggle('open');$('.menu-backdrop').classList.toggle('open');}
 else if(a==='close-menu'){$('.sidebar').classList.remove('open');$('.menu-backdrop').classList.remove('open');}
 else if(a==='onboard'){onboardStep=0;onboarding();}
 else if(a==='onboard-next'){onboardStep++;onboarding();}
 else if(a==='onboard-back'){onboardStep--;onboarding();}
 else if(a==='onboard-save-payment'){store.payment={issuer:$('#onboard-bank').value,type:'Kredit',last4:'4242'};persist();onboardStep=3;onboarding();render();}
 else if(a==='onboard-skip-payment'){onboardStep=3;onboarding();}
 else if(a==='onboard-finish'){store.onboarded=true;persist();closeDialog();fabOpen=true;renderFab();toast('Buddy siap! Pilih mode perbandingan untuk mulai.');}
});
document.addEventListener('change',event=>{if(event.target.id==='catalog-sort'){catalogSort=event.target.value;renderMain();}if(event.target.id==='compare-sort'){compareSort=event.target.value;renderComparison();}});
document.addEventListener('input',event=>{if(['global-search','mobile-search'].includes(event.target.id)){query=event.target.value;if(page!=='explore'){page='explore';document.querySelectorAll('[data-action="nav"]').forEach(b=>{b.classList.toggle('active',b.dataset.page===page);if(b.classList.contains('nav-btn')){if(b.dataset.page===page)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');}});}const mobile=event.target.id==='mobile-search',pos=event.target.selectionStart;renderMain();if(mobile){const input=$('#mobile-search');input.focus();try{input.setSelectionRange(pos,pos);}catch{}}const global=$('#global-search');if(global)global.value=query;}});
document.addEventListener('submit',event=>{
 const form=event.target;if(!['payment-form','alert-form','profile-form','location-form','feedback-form'].includes(form.id))return;event.preventDefault();if(!form.checkValidity()){form.reportValidity();return;}
 if(form.id==='payment-form'){store.payment={issuer:$('#payment-issuer').value,type:formPaymentType,last4:$('#payment-last4')?.value||'—'};persist();closeDialog();render();toast('Preferensi pembayaran disimpan.');}
 else if(form.id==='alert-form'){const id=Number(form.dataset.id),value=Number($('#target-price').value);store.thresholds[id]=value;if(!store.saved.includes(id))store.saved.push(id);persist();closeDialog();render();toast(lowest(product(id))<=value?'Target tersimpan. Harga demo sudah mencapai target!':'Target harga disimpan di daftar pantauan.');}
 else if(form.id==='profile-form'){const name=$('#profile-name').value.trim();if(name.length<2){$('#profile-name').setCustomValidity('Masukkan minimal 2 karakter.');$('#profile-name').reportValidity();$('#profile-name').setCustomValidity('');return;}store.name=name;persist();closeDialog();render();toast('Nama panggilan disimpan.');}
 else if(form.id==='location-form'){store.postal=$('#postal-code').value;persist();closeDialog();render();toast('Kode pos disimpan. Estimasi demo tidak berubah.');}
 else if(form.id==='feedback-form'){const message=$('#feedback-message').value.trim();if(message.length<10){$('#feedback-message').setCustomValidity('Masukkan minimal 10 karakter.');$('#feedback-message').reportValidity();$('#feedback-message').setCustomValidity('');return;}store.reports.push({type:$('#feedback-type').value,message,date:new Date().toISOString()});persist();renderMain();toast('Masukan tersimpan lokal. Belum dikirim ke server.');}
});
document.addEventListener('keydown',event=>{
 if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();if($('#dialog-root').firstChild)return;const input=window.innerWidth<=560?$('#mobile-search'):$('#global-search');if(input)input.focus();else{navigate('explore');$('#mobile-search')?.focus();}}
 if(event.key==='Escape'){if($('#dialog-root').firstChild)closeDialog();else if(fabOpen){fabOpen=false;renderFab();}else if($('.sidebar.open')){$('.sidebar').classList.remove('open');$('.menu-backdrop').classList.remove('open');}}
 if(event.key==='Tab'&&$('.dialog')){const dialog=$('.dialog'),focusable=[...dialog.querySelectorAll('button:not([disabled]),input:not([disabled]),select,textarea,a[href],summary')].filter(el=>el.getClientRects().length);const first=focusable[0],last=focusable[focusable.length-1];if(event.shiftKey&&(document.activeElement===first||document.activeElement===dialog)){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}
});
window.addEventListener('resize',()=>{const mobile=$('.search-mobile');if(mobile)mobile.style.display=window.innerWidth<=560?'flex':'none';});
render();
